static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    ConvStandard3dSquareInputSquareKernelCustomTilingData tiling;

    // 输入 x: [N, Cin, D, H, W]
    const gert::Shape* xShape = context->GetInputShape(0);
    // 权重 weight: [Cout, Cin, K, K, K]
    const gert::Shape* wShape = context->GetInputShape(1);

    auto dimsX = xShape->GetOriginShape().GetDims();
    auto dimsW = wShape->GetOriginShape().GetDims();

    if (dimsX.size() != 5 || dimsW.size() != 5) {
        return ge::GRAPH_FAILED;
    }

    uint32_t N    = static_cast<uint32_t>(dimsX[0]);
    uint32_t Cin  = static_cast<uint32_t>(dimsX[1]);
    uint32_t D    = static_cast<uint32_t>(dimsX[2]);
    uint32_t H    = static_cast<uint32_t>(dimsX[3]);
    uint32_t W    = static_cast<uint32_t>(dimsX[4]);
    uint32_t Cout = static_cast<uint32_t>(dimsW[0]);
    uint32_t K    = static_cast<uint32_t>(dimsW[2]); // square kernel

    uint32_t channelStride = D * H * W;
    uint32_t totalSpatial  = N * channelStride;

    // 简单设置 blockdim 和 tileNum（演示用）
    const uint32_t BLOCK_DIM = 1;
    const uint32_t TILE_NUM  = 8;

    context->SetBlockDim(BLOCK_DIM);
    tiling.set_totalSpatial(totalSpatial);
    tiling.set_cin(Cin);
    tiling.set_cout(Cout);
    tiling.set_channelStride(channelStride);
    tiling.set_tileNum(TILE_NUM);

    // 保存 tiling
    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());
    context->SetTilingKey(1);

    // workspace
    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0;

    return ge::GRAPH_SUCCESS;
}
}

namespace ge {
static ge::graphStatus InferShape(gert::InferShapeContext* context)
{
    // x: [N, Cin, D, H, W], weight: [Cout, Cin, K, K, K]
    const gert::Shape* xShape = context->GetInputShape(0);
    const gert::Shape* wShape = context->GetInputShape(1);

    auto dimsX = xShape->GetOriginShape().GetDims();
    auto dimsW = wShape->GetOriginShape().GetDims();

    if (dimsX.size() != 5 || dimsW.size() != 5) {
        return GRAPH_FAILED;
    }

    int64_t N    = dimsX[0];
    int64_t D    = dimsX[2];
    int64_t H    = dimsX[3];
    int64_t W    = dimsX[4];
    int64_t Cout = dimsW[0];
    int64_t K    = dimsW[2];

    // 仅演示：假设 stride=1, padding=0, dilation=1
    int64_t Dout = D - K + 1;
    int64_t Hout = H - K + 1;
    int64_t Wout = W - K + 1;

    if (Dout <= 0 || Hout <= 0 || Wout <= 0) {
        return GRAPH_FAILED;
    }

    gert::Shape* yShape = context->GetOutputShape(0);
    std::vector<int64_t> out = {N, Cout, Dout, Hout, Wout};
    yShape->SetDim(out);

    return GRAPH_SUCCESS;
}

