ge::Shape srcShape(shapeVec);
uint32_t maxValue = 0;
uint32_t minValue = 0;
AscendC::GetConfusionTransposeMaxMinTmpSize(srcShape, sizeof(half), maxValue, minValue);
// This example is used only as an example. Obtain the minimum value and pass it to ensure that the
